/// Single place for the working name; rename here only.
pub const APP_NAME: &str = "Tessera";

/// Third-party license notices (generated by `development/gen-licenses.py`), shown on About.
pub const LICENSES: &str = include_str!("../../THIRD-PARTY-LICENSES.md");

#[derive(serde::Serialize, Debug, PartialEq, Eq)]
pub struct AppInfo {
    pub name: &'static str,
    pub version: &'static str,
    pub repo_url: String,
    pub license: &'static str,
}

pub fn info() -> AppInfo {
    AppInfo {
        name: APP_NAME,
        version: env!("CARGO_PKG_VERSION"),
        repo_url: format!("https://github.com/{}", crate::update::REPO),
        license: "MIT",
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn info_and_licenses_are_filled_in() {
        let i = info();
        assert_eq!((i.name, i.license), (APP_NAME, "MIT"));
        assert_eq!(i.repo_url, "https://github.com/kaan0d/Tessera");
        assert!(i.version.split('.').count() == 3);
        // the notices carry the ffmpeg section and real crate texts
        assert!(LICENSES.contains("FFmpeg") && LICENSES.contains("LGPL"));
        assert!(LICENSES.contains("Permission is hereby granted"));
        assert!(
            LICENSES.len() < 600_000,
            "keep the embedded file reasonable"
        );
    }
}
